int solve(int T,int C,int U,int blank,const double*x,const int32_t*y,double*loss,double*g){
    if(impossible(T,C,U,y,loss,g))return 1;
    int S=2*U+1;
    uintptr_t start=((uintptr_t)(g+T*C)+64+7)&~(uintptr_t)7;
